<?php $page='skills';require __DIR__.'/_head.php';$msg='';if(isset($_GET['delete'])){check_csrf();db()->prepare('DELETE FROM skills WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:skills.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('INSERT INTO skills(name,group_name,description,sort_order) VALUES(?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['group_name']),trim($_POST['description']),intval($_POST['sort_order'])]);$msg='Skill added.';}$rows=db()->query('SELECT * FROM skills ORDER BY sort_order,id')->fetchAll();?><div class="topbar"><h1>Skills</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="row"><label>Skill<input name="name" required></label><label>Group<input name="group_name" placeholder="Frontend / Backend / Growth" required></label></div><div class="row"><label>Description<input name="description"></label><label>Order<input type="number" name="sort_order" value="0"></label></div><button class="btn primary">Add skill</button></form></div><div class="panel" style="margin-top:20px"><table class="table"><tr><th>Skill</th><th>Group</th><th>Description</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['group_name'])?></td><td><?=e($r['description'])?></td><td><a class="btn danger" href="?delete=<?=$r['id']?>&csrf=<?=e(csrf())?>">Delete</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';
